// Deja la respuesta en «output» (lo que pinta el chat) y añade las fuentes recuperadas.
const MOTOR = 'OpenAI';
const ALMACEN = 'Qdrant · nexora_guias';
const r = $input.first().json;

const fuentes = [];
const vistos = new Set();
const aJson = (x) => {
  if (typeof x !== 'string') return x;
  try { return JSON.parse(x); } catch { return x; }
};
const recorrer = (x) => {
  x = aJson(x);
  if (Array.isArray(x)) return x.forEach(recorrer);
  if (!x || typeof x !== 'object') return;
  if (x.pageContent) {
    const meta = x.metadata ?? {};
    const clave = `${meta.fichero}|${meta.loc?.pageNumber}|${x.pageContent.slice(0, 60)}`;
    if (vistos.has(clave)) return;
    vistos.add(clave);
    fuentes.push({
      fichero: meta.fichero ?? 'sin nombre',
      titulo: meta.titulo ?? null,
      categoria: meta.categoria ?? null,
      capa: meta.capa ?? null,
      pagina: meta.loc?.pageNumber ?? null,
      extracto: x.pageContent.replace(/\s+/g, ' ').trim().slice(0, 220),
    });
    return;
  }
  if (x.text) return recorrer(x.text);
  if (x.response) return recorrer(x.response);
};
for (const paso of r.intermediateSteps ?? []) recorrer(paso.observation);

// Si el redactor falla (cuota, demasiadas búsquedas…), se explica en el chat en vez de romperlo.
const texto = r.output ?? (r.error ? `⚠️ El redactor no ha podido terminar: ${String(r.error).slice(0, 160)}` : '');

return [{ json: {
  output: `[${MOTOR}] ${texto}`,
  respuesta: texto,
  error: r.error ?? null,
  motor: MOTOR,
  almacen: ALMACEN,
  fuentes,
} }];

